void dfs(char[][] b, int r, int c, Node node, List<String> res) {
    if (r < 0 || c < 0 || r >= b.length || c >= b[0].length || b[r][c] == '#') return;
    Node next = node.next[b[r][c] - 'a'];
    if (next == null) return;
    if (next.word != null) {
        res.add(next.word);
        next.word = null;
    }
    char ch = b[r][c];
    b[r][c] = '#';
    dfs(b, r + 1, c, next, res);
    dfs(b, r - 1, c, next, res);
    dfs(b, r, c + 1, next, res);
    dfs(b, r, c - 1, next, res);
    b[r][c] = ch;
}

